{
  "name": "@redivo/opencode",
  "version": "1.2.2",
  "description": "Redivo AI provider plugin for OpenCode — use GPT-5.3, GPT-5.4, GPT-5.5, and more via your Redivo AI account",
  "type": "module",
  "main": "./dist/server.js",
  "types": "./dist/server.d.ts",
  "exports": {
    "./server": {
      "import": "./dist/server.js"
    },
    "./tui": {
      "import": "./dist/tui.js"
    }
  },
  "oc-plugin": [
    [
      "server"
    ],
    [
      "tui"
    ]
  ],
  "publishConfig": {
    "access": "public"
  },
  "bin": {
    "redivo": "dist/cli.js"
  },
  "files": [
    "dist",
    "README.md",
    "LICENSE"
  ],
  "scripts": {
    "build": "tsc",
    "typecheck": "tsc --noEmit",
    "prepare": "npm run build"
  },
  "keywords": [
    "opencode",
    "plugin",
    "redivo",
    "ai",
    "gpt-5",
    "provider"
  ],
  "author": "Redivo AI",
  "license": "MIT",
  "engines": {
    "node": ">=18.0.0"
  },
  "peerDependencies": {
    "@opencode-ai/plugin": "^1.4.0"
  },
  "devDependencies": {
    "@opencode-ai/plugin": "^1.14.33",
    "@types/node": "^25.6.0",
    "typescript": "^6.0.3"
  },
  "dependencies": {
    "@clack/prompts": "^1.3.0",
    "@opentui/core": "^0.2.2",
    "@opentui/solid": "^0.2.2",
    "jsonc-parser": "^3.3.1",
    "picocolors": "^1.1.1"
  },
  "overrides": {
    "uuid": "14.0.0"
  }
}
